function validate([sentence, discount]) {
  if (typeof sentence !== 'string' || sentence.length < 1 || sentence.length > 100000) return 'sentence needs 1 to 10^5 characters.';
  if (!/^[a-z0-9 $]+$/.test(sentence)) return 'sentence may contain only lowercase letters, digits, spaces and $.';
  if (sentence[0] === ' ' || sentence[sentence.length - 1] === ' ' || sentence.includes('  ')) return 'Words must be separated by single spaces with none at the ends.';
  for (const word of sentence.split(' ')) {
    if (!/^\$\d+$/.test(word)) continue;
    if (word[1] === '0') return 'Prices are positive and have no leading zeros.';
    if (word.length > 11) return 'Prices have at most 10 digits.';
  }
  if (!Number.isInteger(discount) || discount < 0 || discount > 100) return 'discount is a whole number from 0 to 100.';
  return null;
}

