function discountPrices(sentence, discount) {
  let out = '';
  let start = 0;
  for (let i = 0; i <= sentence.length; i++) {
    if (i < sentence.length && sentence[i] !== ' ') continue;
    const w = sentence.substring(start, i);
    let ok = w.length > 1 && w[0] === '$';
    for (let k = 1; k < w.length && ok; k++) if (w[k] < '0' || w[k] > '9') ok = false;
    out += ok ? '$' + (parseInt(w.substring(1), 10) * (100 - discount) / 100).toFixed(2) : w;
    if (i < sentence.length) out += ' ';
    start = i + 1;
  }
  return out;
}

