function generate(rand, size) {
  const int = (low, high) => low + Math.floor(rand() * (high - low + 1));
  const large = size === 'large';
  const letters = 'abcdefghijklmnopqrstuvwxyz';
  const digits = (count, lead) => {
    let s = lead ? String(int(1, 9)) : '';
    while (s.length < count) s += String(int(0, 9));
    return s;
  };
  const price = () => '$' + digits(rand() < 0.2 ? 10 : int(1, rand() < 0.5 ? 3 : 10), true);
  const letterWord = () => Array.from({ length: int(1, 6) }, () => letters[int(0, 25)]).join('');
  const makeWord = () => {
    const r = rand();
    if (r < 0.45) return price();
    if (r < 0.6) return letterWord();
    if (r < 0.7) return digits(int(1, 6), rand() < 0.8);
    if (r < 0.75) return '$';
    if (r < 0.8) return digits(int(1, 3), true) + '$';
    if (r < 0.85) return '$' + price();
    if (r < 0.9) return price() + letters[int(0, 25)];
    if (r < 0.95) return price() + '$';
    return letters[int(0, 25)] + price();
  };
  const roll = rand();
  const discount = roll < 0.15 ? 0 : roll < 0.3 ? 100 : int(0, 100);
  const words = [];
  if (large) {
    let length = -1;
    while (true) {
      const word = makeWord();
      if (length + 1 + word.length > 9990) break;
      words.push(word);
      length += 1 + word.length;
    }
  } else {
    const count = int(1, 8);
    for (let i = 0; i < count; i++) words.push(makeWord());
  }
  return [words.join(' '), discount];
}
